package main

import "fmt"

func Map[T any, U any](s []T, f func(T) U) []U {
	out := make([]U, 0, len(s))
	for _, v := range s {
		out = append(out, f(v))
	}
	return out
}

func Filter[T any](s []T, keep func(T) bool) []T {
	out := make([]T, 0, len(s))
	for _, v := range s {
		if keep(v) {
			out = append(out, v)
		}
	}
	return out
}

func Reduce[T any, U any](s []T, initVal U, f func(U, T) U) U {
	acc := initVal
	for _, v := range s {
		acc = f(acc, v)
	}
	return acc
}

func main() {
	nums := []int{1, 2, 3, 4}
	fmt.Println(Map(nums, func(i int) string { return fmt.Sprint(i * i) }))
	fmt.Println(Filter(nums, func(i int) bool { return i%2 == 0 }))
	fmt.Println(Reduce(nums, 0, func(sum, i int) int { return sum + i }))
}

