package main

import "fmt"

// 泛型：元素类型必须一致，但具体类型可以换
func Sum[T ~int | ~float64](s []T) T {
	var total T
	for _, v := range s {
		total += v
	}
	return total
}

// 接口：行为一致即可，具体类型可以各不相同
type Shape interface {
	Area() float64
}

type Rect struct {
	W, H float64
}

func (r Rect) Area() float64 { return r.W * r.H }

func main() {
	fmt.Println(Sum([]int{1, 2, 3}))
	fmt.Println(Sum([]float64{1.5, 2.5}))

	shapes := []Shape{Rect{W: 2, H: 3}, Rect{W: 1, H: 1}}
	for _, s := range shapes {
		fmt.Println(s.Area())
	}
}

package main

import (
	"fmt"
	"slices"
)

// 约束：底层类型是整数的自定义类型也算
type Integer interface {
	~int | ~int64
}

// 泛型结构体 + 泛型方法
type Stack[T any] struct {
	items []T
}

func (s *Stack[T]) Push(v T) {
	s.items = append(s.items, v)
}

// 泛型函数，用自定义约束
func Sum[T Integer](s []T) T {
	var total T
	for _, v := range s {
		total += v
	}
	return total
}

func main() {
	st := &Stack[int]{}
	st.Push(1)
	st.Push(2)
	fmt.Println(st.items, Sum(st.items))

	nums := []int{3, 1, 2}
	slices.Sort(nums)
	fmt.Println(nums, slices.Contains(nums, 2))
}
